# genex.toml: physics is on unless a table turns it off; a game built on it says so
# (off, every Rapier call fails to compile: build-failed)
[physics]
enabled = true

// src/facets/yard.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs, #[derive(Default)]) holds crates: Vec<RigidBodyHandle>,
// bombs: Vec<(RigidBodyHandle, ColliderHandle)>, trolley: Option<RigidBodyHandle>,
// ball: Option<(RigidBodyHandle, ColliderHandle)>, blasts: u32, pushed: usize, shots: u32, hits: u32.
use super::World;
use genex::physics::{Ball, ColliderBuilder, Pose, QueryFilter, Ray, RigidBodyBuilder, RigidBodyHandle, RopeJointBuilder};
use genex::prelude::*;

/// Crates in the wall: ten wide, ten high, twenty deep.
const CRATES: usize = 2000;
/// The wall's slots that hold a bomb instead of a crate: four in the front, where the ball swings.
const BOMB_SLOTS: [usize; 4] = [44, 45, 54, 55];
/// The wrecking ball's rope, in metres.
const ROPE: f32 = 8.0;
/// Where the player shoots from, and at.
const EYE: Vec3 = Vec3::new(0.3, 2.0, 14.0);
const AIM_AT: Vec3 = Vec3::new(0.3, 4.0, -8.0);

/// A draw id that stays with one body: its handle's slot and generation.
fn body_id(handle: RigidBodyHandle) -> u64 {
    let (slot, generation) = handle.into_raw_parts();
    u64::from(slot) | (u64::from(generation) << 32)
}

/// Push every dynamic body within `radius` of `at` away, harder the closer: up to `strength` m/s.
fn explode(physics: &mut PhysicsWorld, at: Vec3, radius: f32, strength: f32) -> usize {
    let blast = Ball::new(radius);
    let overlapping = physics.intersect_shape(Pose::from_translation(at), &blast, QueryFilter::only_dynamic());
    let near: Vec<RigidBodyHandle> = overlapping.filter_map(|(_, collider)| collider.parent()).collect();
    for handle in &near {
        let Some(body) = physics.bodies.get_mut(*handle) else { continue };
        let away = body.translation() - at;
        let falloff = 1.0 - (away.length() / radius).min(1.0);
        body.apply_impulse((away.normalize_or_zero() + Vec3::Y * 0.5) * strength * falloff * body.mass(), true);
    }
    near.len()
}

/// The level: a fixed ground, the wall of crates with its bombs, the trolley and its ball.
fn build(world: &mut World, physics: &mut PhysicsWorld) {
    let ground = ColliderBuilder::cuboid(60.0, 0.5, 60.0).friction(0.8);
    physics.insert(RigidBodyBuilder::fixed().translation(vec3(0.0, -0.5, 0.0)), ground);
    for i in 0..CRATES {
        let at = vec3((i % 10) as f32 - 4.5, 0.5 + (i / 10 % 10) as f32, -6.0 - (i / 100) as f32);
        let collider = ColliderBuilder::cuboid(0.5, 0.5, 0.5).mass(20.0).friction(0.7).restitution(0.05);
        let placed = physics.insert(RigidBodyBuilder::dynamic().translation(at), collider);
        if BOMB_SLOTS.contains(&i) {
            world.bombs.push(placed);
        } else {
            world.crates.push(placed.0);
        }
    }
    // The crane: a kinematic trolley over the wall's front; a 600 kg ball hangs from it on a rope.
    let trolley = physics.insert_body(RigidBodyBuilder::kinematic_position_based().translation(vec3(-12.0, 13.0, -6.0)));
    let wrecking = RigidBodyBuilder::dynamic().translation(vec3(-12.0, 5.0, -6.0)).linear_damping(0.05);
    let ball = physics.insert(wrecking, ColliderBuilder::ball(1.0).mass(600.0).restitution(0.1));
    physics.insert_impulse_joint(trolley, ball.0, RopeJointBuilder::new(ROPE));
    (world.trolley, world.ball) = (Some(trolley), Some(ball));
}

/// Set off every bomb the ball touches or something knocked flying: it goes, and pushes what is near.
fn bombs(world: &mut World, physics: &mut PhysicsWorld) {
    let ball = world.ball.map(|(_, collider)| collider);
    let mut fired = Vec::new();
    world.bombs.retain(|&(body, collider)| {
        let touched = ball.is_some_and(|ball| physics.contact_pair(ball, collider).is_some_and(|pair| pair.has_any_active_contact()));
        let struck = physics.bodies.get(body).is_some_and(|bomb| bomb.linvel().length() > 6.0);
        if touched || struck {
            fired.push(body);
        }
        !(touched || struck)
    });
    for body in fired {
        let Some(at) = physics.bodies.get(body).map(|bomb| bomb.translation()) else { continue };
        physics.remove_body(body);
        world.pushed += explode(physics, at, 5.0, 10.0);
        world.blasts += 1;
    }
}

/// Fire a CCD shot from the eye: a 10 cm, 30 kg ball at 60 m/s; the ray says what it will hit first.
fn shoot(world: &mut World, physics: &mut PhysicsWorld) {
    let aim = (AIM_AT - EYE).normalize_or_zero();
    let ray = Ray::new(EYE, aim);
    if let Some((_, toi)) = physics.cast_ray(&ray, 100.0, true, QueryFilter::default()) {
        world.hits += u32::from(ray.point_at(toi).z < 0.0); // the wall or a bomb, not the ground in front
    }
    let shot = RigidBodyBuilder::dynamic().translation(EYE).linvel(aim * 60.0).ccd_enabled(true);
    physics.insert(shot, ColliderBuilder::ball(0.1).mass(30.0));
    world.shots += 1;
}

pub fn wire(game: &mut Game<World>) {
    game.on_reset(|sim, _seed, _rng, _gfx| {
        let (world, physics) = sim.split();
        build(world, physics);
    });
    game.on_update(|sim, ctx| {
        let (world, physics) = sim.split();
        // The crane runs the ball through the wall and back every 20 s.
        let phase = (ctx.tick % 1200) as f32 / 600.0;
        if let Some(body) = world.trolley.and_then(|handle| physics.bodies.get_mut(handle)) {
            body.set_next_kinematic_translation(vec3(-12.0 + 24.0 * (1.0 - (phase - 1.0).abs()), 13.0, -6.0));
        }
        bombs(world, physics);
        if ctx.keys.pressed(Key::Space) {
            shoot(world, physics);
        }
    });
    game.on_draw(|sim, frame, _camera| {
        let draw = |frame: &mut Frame, handle: RigidBodyHandle, size: f32, color: Color| {
            let Some(body) = sim.physics.bodies.get(handle) else { return };
            let at = Transform::from_translation(body.translation()).with_rotation(*body.rotation()).with_scale(vec3(size, size, size));
            frame.id(body_id(handle)).cube(at, color);
        };
        frame.tag("crates");
        for handle in &sim.world.crates {
            draw(frame, *handle, 1.0, Color::rgb(170, 120, 70));
        }
        frame.tag("bombs");
        for (handle, _) in &sim.world.bombs {
            draw(frame, *handle, 1.0, Color::RED);
        }
        frame.tag("wrecking-ball");
        let trolley = sim.world.trolley.and_then(|handle| sim.physics.bodies.get(handle));
        let ball = sim.world.ball.and_then(|(handle, _)| sim.physics.bodies.get(handle));
        if let (Some(trolley), Some(ball)) = (trolley, ball) {
            frame.id("wrecking-ball").sphere(ball.translation(), 1.0, Color::rgb(60, 60, 70));
            frame.end_id().lines(&[trolley.translation(), ball.translation()], Color::BLACK);
        }
        frame.end_id();
    });
    // One probe per mechanic, each a few numbers that say whether it works.
    game.probe("pile", |sim| {
        // A crate knocked over: its up axis tipped past 45 degrees.
        let toppled = sim.world.crates.iter().filter(|h| sim.physics.bodies.get(**h).is_some_and(|c| (*c.rotation() * Vec3::Y).y < 0.7)).count();
        json!({ "crates": sim.world.crates.len(), "toppled": toppled })
    });
    game.probe("blast", |sim| json!({ "bombs": sim.world.bombs.len(), "blasts": sim.world.blasts, "pushed": sim.world.pushed }));
    game.probe("wrecking-ball", |sim| {
        let at = |handle: Option<RigidBodyHandle>| handle.and_then(|h| sim.physics.bodies.get(h)).map(|body| body.translation());
        let (trolley, ball) = (at(sim.world.trolley), at(sim.world.ball.map(|(handle, _)| handle)));
        let rope = trolley.zip(ball).map(|(t, b)| (t - b).length());
        json!({ "onRope": rope.is_some_and(|length| length <= ROPE + 0.05), "low": ball.is_some_and(|b| b.y < 6.0) })
    });
    game.probe("shots", |sim| json!({ "fired": sim.world.shots, "aimedAtWall": sim.world.hits }));
    // A load wakes every body it puts back, so how many are awake is display only.
    game.probe_volatile("awake", |sim| json!(sim.physics.active_bodies().count()));
}
